import{_ as t,o as a,c as n,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Agent Runtime","description":"createAgent、State 与 Context、上下文工程、Middleware、流式恢复与控制模式边界。","frontmatter":{"title":"Agent Runtime","description":"createAgent、State 与 Context、上下文工程、Middleware、流式恢复与控制模式边界。"},"headers":[],"relativePath":"ts-ai/agent/runtime/index.md","filePath":"ts-ai/agent/runtime/index.md","lastUpdated":1786083160000}'),i={name:"ts-ai/agent/runtime/index.md"};function s(o,e,d,l,c,h){return a(),n("div",null,[...e[0]||(e[0]=[r(`<h1 id="agent-runtime" tabindex="-1">Agent Runtime <a class="header-anchor" href="#agent-runtime" aria-label="Permalink to &quot;Agent Runtime&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本分组讲解 LangChain.js <strong>Agent Harness</strong>：在 Model 之上驱动工具循环、管理 State 与 Context、实施 Guardrails，并处理流式与取消。核心等式：<strong>Agent = Model + Harness</strong>；默认入口是 <code>langchain</code> 包的 <code>createAgent</code>。</p><h2 id="分组地图" tabindex="-1">分组地图 <a class="header-anchor" href="#分组地图" aria-label="Permalink to &quot;分组地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文章</th><th>负责什么</th><th>不负责什么</th></tr></thead><tbody><tr><td><a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a></td><td>执行循环、<code>model</code> / <code>tools</code> / <code>systemPrompt</code>、<code>invoke</code> 与轨迹</td><td>Middleware 细节、LangGraph 手写图</td></tr><tr><td><a href="/ts-ai/agent/runtime/state-context-lifecycle">State、Context 与生命周期</a></td><td><code>messages</code>、contextSchema、<code>thread_id</code>、一次 Run 阶段</td><td>Store 长期记忆、Interrupt</td></tr><tr><td><a href="/ts-ai/agent/runtime/context-engineering">上下文工程</a></td><td>system、动态拼装、工具结果进 prompt、预算链</td><td>向量库与分块实现（→ RAG）</td></tr><tr><td><a href="/ts-ai/agent/runtime/middleware-guardrails">Middleware 与 Guardrails</a></td><td>钩子时机、输入/输出/工具 ACL</td><td>NestJS HTTP Guard</td></tr><tr><td><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式事件、取消与恢复</a></td><td>Agent 上 <code>stream</code> / <code>streamEvents</code>、<code>AbortSignal</code></td><td>SSE 协议与前端渲染</td></tr><tr><td><a href="/ts-ai/agent/runtime/react-router-planner">ReAct、Router 与 Planner</a></td><td>三种控制模式定义与选型</td><td>Supervisor 图实现</td></tr><tr><td><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a></td><td>三层编排决策树</td><td>LangGraph API 逐条讲解</td></tr></tbody></table><p>模块收束不在本组：见平级 <a href="/ts-ai/agent/assembly/">组装配方与能力自检</a>。</p><h2 id="与相邻分组" tabindex="-1">与相邻分组 <a class="header-anchor" href="#与相邻分组" aria-label="Permalink to &quot;与相邻分组&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LangChain.js 核心（Runnable、Message）</span></span>
<span class="line"><span>  → 模型与输出（参数、结构化、上下文预算）</span></span>
<span class="line"><span>  → 工具与 MCP（Schema、ToolMessage、Context 注入）</span></span>
<span class="line"><span>  → Agent Runtime（本分组）</span></span>
<span class="line"><span>  → 组装配方与能力自检（模块收束）</span></span>
<span class="line"><span>  → 工作流与多 Agent（复杂图、Interrupt、多 Agent）</span></span>
<span class="line"><span>  → 全栈集成（SSE、UI 流式）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><table tabindex="0"><thead><tr><th>需求</th><th>去哪里</th></tr></thead><tbody><tr><td><code>pipe</code>、LCEL <code>streamEvents</code> 事件表</td><td><a href="/ts-ai/agent/langchain-core/runnable-composition-events">Runnable 组合、容错与事件</a></td></tr><tr><td>token 计数与裁剪算法</td><td><a href="/ts-ai/agent/models-output/context-budget-trimming">上下文预算与裁剪</a></td></tr><tr><td>Checkpoint、Interrupt、Command</td><td><a href="/ts-ai/workflow/durable-execution/">工作流持久执行</a></td></tr><tr><td>NestJS 暴露 SSE</td><td><a href="/ts-ai/backend/api-realtime/sse-streaming">SSE 流式响应</a></td></tr></tbody></table><h2 id="建议学习路径" tabindex="-1">建议学习路径 <a class="header-anchor" href="#建议学习路径" aria-label="Permalink to &quot;建议学习路径&quot;">​</a></h2><p><strong>路径 A：最小可运行 Agent</strong></p><ol><li><a href="/ts-ai/agent/runtime/create-agent">使用 createAgent 创建 Agent</a> — 理解 ReAct 循环与查订单示例。</li><li><a href="/ts-ai/agent/runtime/state-context-lifecycle">State、Context 与生命周期</a> — 区分 <code>thread_id</code> 与 <code>context</code>。</li><li><a href="/ts-ai/agent/runtime/streaming-cancellation-recovery">流式事件、取消与恢复</a> — 对接产品进度与取消。</li></ol><p><strong>路径 B：可上线 Harness</strong></p><ol><li>完成路径 A。</li><li><a href="/ts-ai/agent/runtime/context-engineering">上下文工程</a> — 检索与用户画像注入。</li><li><a href="/ts-ai/agent/runtime/middleware-guardrails">Middleware 与 Guardrails</a> — ACL 与观测钩子。</li><li><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a> — 确认不必过早上 LangGraph。</li><li>进入 <a href="/ts-ai/agent/assembly/assembly-recipes-checklist">Agent 组装配方与能力自检</a> — 串起来并勾选自检。</li></ol><p><strong>路径 C：架构选型</strong></p><ol><li><a href="/ts-ai/agent/runtime/react-router-planner">ReAct、Router 与 Planner</a> — 控制模式对比。</li><li><a href="/ts-ai/agent/runtime/agent-chain-workflow-boundaries">Agent、Chain 与 Workflow 的边界</a> — 决策树与复查条件。</li><li>进入 <a href="/ts-ai/agent/assembly/assembly-recipes-checklist">Agent 组装配方与能力自检</a> — 用配方验证选型。</li><li>若结论为 Workflow → <a href="/ts-ai/workflow/langgraph-core/workflow-modeling">工作流建模</a>。</li></ol><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><ul><li>已完成 <a href="/ts-ai/agent/langchain-core/">LangChain.js 核心</a> 中的 Runnable 与 Message。</li><li>已定义至少一个 <a href="/ts-ai/agent/tools-mcp/tools-schemas">Tool 与 Schema</a>。</li><li>本地可运行 <code>createAgent</code>（<code>langchain</code>、<code>@langchain/core</code>、至少一个 ChatModel 集成包）。</li></ul><h2 id="验收清单" tabindex="-1">验收清单 <a class="header-anchor" href="#验收清单" aria-label="Permalink to &quot;验收清单&quot;">​</a></h2><ul><li>[ ] 能解释 Agent 执行循环中 Model、Tools、State、停止条件各自职责。</li><li>[ ] 能用 <code>createAgent</code> + <code>invoke</code> 跑通带工具的薄业务示例并读取完整 <code>messages</code> 轨迹。</li><li>[ ] 能说明 State 与 Context 区别，并正确使用 <code>thread_id</code>（配合 checkpointer）。</li><li>[ ] 能在 Agent 上使用 <code>streamEvents</code> 或 <code>stream</code> 暴露中间进度，并用 <code>AbortSignal</code> 取消。</li><li>[ ] 能根据场景在 Chain、Agent、Workflow 之间选型，并知道复杂 Interrupt 应转到 <code>/ts-ai/workflow/</code>。</li><li>[ ] 能按<a href="/ts-ai/agent/assembly/assembly-recipes-checklist">组装配方与能力自检</a>选出一种组装并勾完跨组清单。</li></ul>`,20)])])}const u=t(i,[["render",s]]);export{p as __pageData,u as default};
